contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Test: owner withdraw behavior with arbitrary amount
    function run(uint withdrawAmount) public payable {
        // No precondition on msg.value; this contract is the owner of c
        // Record state before the withdraw attempt
        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        // Attempt withdraw as owner; must be a top-level state-changing call on c
        bool withdrewReverted;
        c.withdraw(withdrawAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrewReverted = true;
        } else {
            withdrewReverted = false;
        }

        // Observe state after the call
        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        // General rule:
        // - If withdraw succeeded: balance did not increase (balAfter <= balBefore) and depositsCount unchanged.
        // - If withdraw reverted: both balance and depositsCount remain exactly as before.
        assert(
            (!withdrewReverted && depositsAfter == depositsBefore && balAfter <= balBefore)
            || (withdrewReverted && depositsAfter == depositsBefore && balAfter == balBefore)
        );
    }

    receive() external payable { }
}

