// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 withdrawAmount) internal {
        uint balBefore = address(c).balance;
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }
        uint balAfter = address(c).balance;
        uint256 depositsAfter;
        try c.depositsCount() returns (uint256 __r) { depositsAfter = __r; } catch { return; }
        assertTrue((!withdrewReverted && depositsAfter == depositsBefore && balAfter <= balBefore)
            || (withdrewReverted && depositsAfter == depositsBefore && balAfter == balBefore));
    }

    function testFuzz_run(uint256 withdrawAmount) public {
        _run(withdrawAmount);
    }

    receive() external payable { }
}
